def _seed_intervals():
    """Stable interval catalogue; max_days_per_request defaults to the Angel One profile (editable later)."""
    from tradealpha.platform.time.intervals import INTERVALS
    from tradealpha.platform.ratelimit.profiles import ANGELONE

    intervals = sa.table("intervals", sa.column("id", sa.Integer), sa.column("code", sa.String),
                         sa.column("seconds", sa.Integer), sa.column("is_native", sa.Boolean),
                         sa.column("max_days_per_request", sa.Integer))
    op.bulk_insert(intervals, [
        {"id": s.id, "code": s.code, "seconds": s.seconds, "is_native": s.is_native,
         "max_days_per_request": ANGELONE.max_days.get(s.code)}
        for s in INTERVALS.values()
    ])


